SELECT tpd.TRADE_ID tradeId, '${effective}' validStatus, tpda.ENTRUST_ID entrustId, pp.PORTFOLIO_ID portfolioId, pp.PORTFOLIO_NAME portfolioName, tpd.FINPROD_TYPE2 finprodType, tpd.FINPROD_ID finprodId, tpda.EXC_DEAL_TYPE excDealType, tpda.CUR_PAIR curPair,tpda.DEAL_MODE dealMode, tpda.OUR_ROLE, ftp.EXC_PS ps, tpd.TRADE_DATE tradeDate, tpd.SETTLE_SPEED settleSpeed, ftp.CALENDAR_ID calendarId, ftp.HOLD_PURPOSE holdPurpose, tpd.SETTLE_DATE settleDate, tpd.DELIVERY_TYPE deliveryType, tpd.UNIT_CPRICE unitCprice, ftp.CCY dealCur, tpd.PRIN_AMT prinAmt, tpd.CCY ccy, tpd.TRADE_AMT tradeAmt, tpda.USD_AMT usdAmt, tpd.REMARK remark, tpd.COUNTER_ID counterId, tpd.TRADER trader, tpd.COUNTER_TRADER counterTrader, tpd.COUNTER_CONTACT counterContact, NULL workflowId, NULL workflowStatus FROM TRD_PRODUCT_DEAL tpd LEFT JOIN FIN_TRADE_PRODUCT ftp ON tpd.TRADE_ID = ftp.FINPROD_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD tpda ON tpd.TRADE_ID = tpda.TRADE_ID LEFT JOIN PTL_TRADE PT ON tpd.TRADE_ID = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO pp ON pp.PORTFOLIO_ID = PT.PORTFOLIO_ID WHERE tpd.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F11,jdbcType=VARCHAR} AND PP.INVEST_YESORNO='Y' AND (PP.PORTFOLIO_ID IN (select PORTFOLIO_ID FROM PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId,jdbcType=VARCHAR}) or pp.PARENT_PORTFOLIO_ID in (select PORTFOLIO_ID FROM PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId,jdbcType=VARCHAR}))
AND (PP.PORTFOLIO_ID IN
#{item,jdbcType=VARCHAR}
OR PP.PARENT_PORTFOLIO_ID IN
#{item,jdbcType=VARCHAR}
)
AND tpda.ENTRUST_ID = #{entrustId,jdbcType=VARCHAR}
AND tpda.EXC_DEAL_TYPE = #{excDealType,jdbcType=VARCHAR}
AND ftp.EXC_PS = #{ps,jdbcType=VARCHAR}
AND tpda.CUR_PAIR IN
#{item,jdbcType=VARCHAR}
AND tpd.TRADE_DATE >= STR_TO_DATE(#{tradeDateBegin,jdbcType=VARCHAR}, '%Y-%m-%d')
AND tpd.TRADE_DATE <= STR_TO_DATE(#{tradeDateEnd,jdbcType=VARCHAR}, '%Y-%m-%d')
AND (tpd.IS_CANCEL IS NULL OR tpd.IS_CANCEL = #{YES_NO_NO,jdbcType=VARCHAR}) AND tpd.TRADE_STATUS = #{TRADE_STATUS_01,jdbcType=VARCHAR}
AND tpd.TRADE_ID = #{tradeId,jdbcType=VARCHAR}

