AND tpd.TRADE_DATE <= STR_TO_DATE(#{tradeDateEnd,jdbcType=VARCHAR}, '%Y-%m-%d')
AND tpd.TRADE_STATUS = #{TRADE_STATUS_03,jdbcType=VARCHAR}
AND tpd.TRADE_ID = #{tradeId,jdbcType=VARCHAR}

